function dataUrlToFile(dataUrl,name){const [head,data]=dataUrl.split(','),mime=(head.match(/data:([^;]+)/)||[])[1]||'image/jpeg',bytes=atob(data),arr=new Uint8Array(bytes.length);for(let i=0;i<bytes.length;i++)arr[i]=bytes.charCodeAt(i);return new File([arr],name,{type:mime})}
async function shareDocument(title,text,images=[]){const files=images.filter(Boolean).map((x,i)=>dataUrlToFile(x,`${title.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}-${i+1}.jpg`));try{if(navigator.share){const data={title,text};if(files.length&&(!navigator.canShare||navigator.canShare({files})))data.files=files;await navigator.share(data);return}throw new Error('unsupported')}catch(err){if(err?.name==='AbortError')return;try{await navigator.clipboard.writeText(text);alert('Sdílení souborů není v tomto prohlížeči dostupné. Údaje byly zkopírovány do schránky.')}catch{downloadShareFiles(files,text,title)}}}
function downloadShareFiles(files,text,title){if(files.length){files.forEach(f=>{const a=document.createElement('a');a.href=URL.createObjectURL(f);a.download=f.name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)})}else{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.download=`${title}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}}
function shareLicense(id){const x=db.licenses[id];if(!x)return;const text=[x.name,x.organization,x.number?`Číslo licence: ${x.number}`:'',x.issuedDate?`Datum získání: ${fmtDate(x.issuedDate)}`:'',x.validUntil?`Platnost do: ${fmtDate(x.validUntil)}`:'Platnost neomezená'].filter(Boolean).join('\n');if(confirm(`Sdílet licenci „${x.name}“ včetně uložených obrázků?`))shareDocument(x.name,text,[x.frontImage,x.backImage])}
function insuranceStatus(x){const today=new Date();today.setHours(0,0,0,0);const from=x.validFrom?new Date(x.validFrom+'T00:00:00'):null,to=x.validUntil?new Date(x.validUntil+'T00:00:00'):null;if(from&&from>today)return {key:'future',label:'Budoucí'};if(to&&to<today)return {key:'expired',label:'Prošlé'};if(to&&Math.ceil((to-today)/86400000)<=30)return {key:'soon',label:'Končí brzy'};return {key:'active',label:'Aktivní'}}
