function siteDiveCount(id){return db.dives.filter(d=>String(d.siteId)===String(id)).length}
let siteMergeMode=false;
let selectedSiteMergeIds=new Set();
function syncSiteMergeSelection(){
  selectedSiteMergeIds=new Set([...document.querySelectorAll("#sitesDbList .site-merge-check:checked")].map(input=>String(input.value)));
  const count=selectedSiteMergeIds.size;
  $("startSiteMerge").classList.toggle("hidden",siteMergeMode);
  $("siteMergeActions").classList.toggle("hidden",!siteMergeMode);
  $("siteMergeCount").textContent=`Vybráno: ${count}`;
  const button=$("continueSiteMerge");
  if(count>=2){button.disabled=false;button.removeAttribute("disabled");button.setAttribute("aria-disabled","false");button.classList.add("merge-ready")}
  else{button.disabled=true;button.setAttribute("disabled","");button.setAttribute("aria-disabled","true");button.classList.remove("merge-ready")}
}
function updateSiteMergeUi(){syncSiteMergeSelection()}
function renderSitesDb(){
  const q=$("siteDbSearch").value.trim().toLowerCase();
  const arr=Object.values(db.sites||{}).filter(x=>`${x.name} ${x.country} ${x.region||""} ${x.ssiId}`.toLowerCase().includes(q)).sort((a,b)=>(a.name||"").localeCompare(b.name||""));
  $("sitesDbStats").textContent=`${arr.length} lokalit · ${db.dives.length} ponorů`;
  $("sitesDbList").innerHTML=arr.map(x=>{
    const id=String(x.ssiId),checked=selectedSiteMergeIds.has(id);
    if(siteMergeMode)return `<div class="db-card merge-site-card${checked?" is-selected":""}" data-merge-id="${esc(id)}" role="group"><input class="site-merge-check" id="mergeSite_${esc(id)}" type="checkbox" value="${esc(id)}" ${checked?"checked":""}><label class="merge-site-content" for="mergeSite_${esc(id)}"><div><h3>${esc(x.name||"Bez názvu")}</h3><p>${esc(x.country||"Země chybí")}${x.region?" · "+esc(x.region):""}</p><small>SSI ID ${x.ssiId}</small></div><div class="db-count">${siteDiveCount(x.ssiId)}<br><small>ponorů</small></div></label></div>`;
    return `<button class="db-card" data-site-edit="${x.ssiId}" type="button"><div><h3>${esc(x.name||"Bez názvu")}</h3><p>${esc(x.country||"Země chybí")}${x.region?" · "+esc(x.region):""}</p><small>SSI ID ${x.ssiId}</small>${!x.name||!x.country?'<span class="warning-badge">Doplnit údaje</span>':""}</div><div class="db-count">${siteDiveCount(x.ssiId)}<br><small>ponorů</small></div></button>`;
  }).join("")||'<div class="empty card">Žádná lokalita.</div>';
  document.querySelectorAll("[data-site-edit]").forEach(button=>button.onclick=()=>openSiteForm(button.dataset.siteEdit));
  document.querySelectorAll("#sitesDbList .site-merge-check").forEach(input=>input.addEventListener("change",()=>{
    const card=input.closest(".merge-site-card");
    card?.classList.toggle("is-selected",input.checked);
    syncSiteMergeSelection();
  }));
  syncSiteMergeSelection();
}
function cancelSiteMerge(){siteMergeMode=false;selectedSiteMergeIds.clear();$('startSiteMerge').setAttribute('aria-pressed','false');$('siteMergeModal').classList.add('hidden');renderSitesDb()}
function openSiteMergeDialog(){if(selectedSiteMergeIds.size<2)return;const sites=[...selectedSiteMergeIds].map(id=>db.sites[String(id)]).filter(Boolean);const diveCount=db.dives.filter(d=>selectedSiteMergeIds.has(String(d.siteId))).length;$('siteMergeSummary').innerHTML=`<strong>${sites.length} lokalit</strong><span>${diveCount} dotčených ponorů</span>`;$('siteMergeTarget').innerHTML=sites.map(x=>`<option value="${x.ssiId}">${esc(x.name||'Bez názvu')} · SSI ID ${x.ssiId} · ${siteDiveCount(x.ssiId)} ponorů</option>`).join('');$('siteMergeModal').classList.remove('hidden')}
function confirmSiteMerge(){const targetId=String($('siteMergeTarget').value);const target=db.sites[targetId];if(!target||selectedSiteMergeIds.size<2)return;const sourceIds=[...selectedSiteMergeIds].filter(id=>id!==targetId);const affected=db.dives.filter(d=>sourceIds.includes(String(d.siteId))).length;const names=sourceIds.map(id=>db.sites[id]?.name||`SSI ID ${id}`).join(', ');if(!confirm(`Sloučit ${sourceIds.length} lokalit do „${target.name}“?

Přepojí se ${affected} ponorů. Odstraněné lokality: ${names}.

Tuto operaci nelze vrátit zpět bez JSON zálohy.`))return;db.dives.forEach(d=>{if(sourceIds.includes(String(d.siteId)))d.siteId=Number(targetId)});sourceIds.forEach(id=>delete db.sites[id]);save();cancelSiteMerge();renderSettings();alert(`Sloučení dokončeno. Přepojeno ponorů: ${affected}.`)}
