function renderDefaults(){const d=db.settings?.defaults||{};$('defaultSuit').value=d.suit||'';$('defaultTankMaterial').value=d.tankMaterial||'';$('defaultTankVolume').value=d.tankVolumeL??'';$('defaultGas').value=d.gas||'';$('defaultWeight').value=d.weightKg??'';$('defaultStartPressure').value=d.startPressureBar??'';$('defaultEndPressure').value=d.endPressureBar??''}
