function openProfileForm(id=null){const x=id?db.profiles[id]:null,e=x?.equipment||{};$('profileForm').classList.remove('hidden');$('profileFormTitle').textContent=x?'Upravit profil':'Přidat profil';$('profileId').value=x?.id||'';$('gearProfileName').value=x?.name||'';$('profileSuit').value=e.suit||'';$('profileTankMaterial').value=e.tankMaterial||'';$('profileTankVolume').value=e.tankVolumeL??'';$('profileGas').value=e.gas||'';$('profileWeight').value=e.weightKg??'';$('profileStartPressure').value=e.startPressureBar??'';$('profileEndPressure').value=e.endPressureBar??'';$('profileForm').scrollIntoView({behavior:'smooth'})}

